from app.models import Base
from sqlalchemy import Table,Column,String,Text,Integer,SmallInteger,BigInteger,DateTime,Numeric,CHAR,ForeignKey,UniqueConstraint,text
from sqlalchemy.dialects.postgresql import UUID,JSONB

def common():return [Column('id',UUID(as_uuid=True),primary_key=True,server_default=text('gen_random_uuid()')),Column('created_at',DateTime(timezone=True),server_default=text('now()')),Column('updated_at',DateTime(timezone=True),server_default=text('now()')),Column('created_by',UUID(as_uuid=True),ForeignKey('users.id')),Column('updated_by',UUID(as_uuid=True),ForeignKey('users.id')),Column('version',Integer,server_default='1')]
def table(name,*columns):return Table(name,Base.metadata,*common(),*columns)
trip_operation_runs_table=table('trip_operation_runs',Column('trip_id',UUID(as_uuid=True),ForeignKey('trips.id'),unique=True),Column('current_phase',String(24)),Column('duty_started_at',DateTime(timezone=True)),Column('duty_started_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('fuel_level_percent',Numeric(5,2)),Column('passenger_started_at',DateTime(timezone=True)),Column('destination_arrived_at',DateTime(timezone=True)),Column('returned_to_garage_at',DateTime(timezone=True)),Column('final_fare_status',String(20)))
trip_pickup_credentials_table=table('trip_pickup_credentials',Column('trip_id',UUID(as_uuid=True),ForeignKey('trips.id'),unique=True),Column('qr_token_hash',CHAR(64)),Column('pin_hash',Text),Column('issued_at',DateTime(timezone=True)),Column('expires_at',DateTime(timezone=True)),Column('verification_status',String(16)),Column('failed_attempts',Integer),Column('verified_at',DateTime(timezone=True)),Column('verified_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')))
trip_operation_events_table=table('trip_operation_events',Column('trip_id',UUID(as_uuid=True),ForeignKey('trips.id')),Column('sequence_no',Integer),Column('event_type',String(32)),Column('phase_after',String(24)),Column('occurred_at',DateTime(timezone=True)),Column('recorded_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('related_entity_type',String(32)),Column('related_entity_id',UUID(as_uuid=True)),Column('note',Text),UniqueConstraint('trip_id','sequence_no'))
trip_odometer_readings_table=table('trip_odometer_readings',Column('trip_id',UUID(as_uuid=True),ForeignKey('trips.id')),Column('reading_type',String(12)),Column('odometer_km',Numeric(12,1)),Column('recorded_at',DateTime(timezone=True)),Column('recorded_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')))
trip_waiting_sessions_table=table('trip_waiting_sessions',Column('trip_id',UUID(as_uuid=True),ForeignKey('trips.id')),Column('started_at',DateTime(timezone=True)),Column('stopped_at',DateTime(timezone=True)),Column('started_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('stopped_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('status',String(12)),Column('note',Text))
trip_extra_stops_table=table('trip_extra_stops',Column('trip_id',UUID(as_uuid=True),ForeignKey('trips.id')),Column('sequence_no',Integer),Column('place_label',String(150)),Column('latitude',Numeric(9,6)),Column('longitude',Numeric(9,6)),Column('proposed_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('proposed_at',DateTime(timezone=True)),Column('approval_status',String(20)),Column('approved_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('approved_at',DateTime(timezone=True)),Column('rejection_reason',Text))
vehicle_operational_expenses_table=table('vehicle_operational_expenses',Column('vehicle_id',UUID(as_uuid=True),ForeignKey('vehicles.id')),Column('trip_id',UUID(as_uuid=True),ForeignKey('trips.id')),Column('expense_type',String(20)),Column('amount',Numeric(12,2)),Column('currency',CHAR(3)),Column('paid_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('recorded_at',DateTime(timezone=True)),Column('odometer_km',Numeric(12,1)),Column('approval_status',String(20)),Column('reimbursement_status',String(20)),Column('approved_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('approved_at',DateTime(timezone=True)),Column('reimbursed_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('reimbursed_at',DateTime(timezone=True)),Column('note',Text))
trip_media_table=table('trip_media',Column('trip_id',UUID(as_uuid=True),ForeignKey('trips.id'),nullable=True),Column('odometer_reading_id',UUID(as_uuid=True),ForeignKey('trip_odometer_readings.id')),Column('expense_id',UUID(as_uuid=True),ForeignKey('vehicle_operational_expenses.id')),Column('vehicle_record_id',UUID(as_uuid=True),ForeignKey('vehicle_records.id')),Column('media_kind',String(24)),Column('storage_key',Text),Column('sha256',CHAR(64)),Column('mime_type',String(100)),Column('byte_size',BigInteger),Column('captured_at',DateTime(timezone=True)),Column('retention_until',DateTime(timezone=True)),Column('uploaded_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')))
trip_fare_calculations_table=table('trip_fare_calculations',Column('trip_id',UUID(as_uuid=True),ForeignKey('trips.id')),Column('calculation_sequence',Integer),Column('source_booking_version',Integer),Column('frozen_rate_snapshot',JSONB),Column('pickup_odometer_reading_id',UUID(as_uuid=True),ForeignKey('trip_odometer_readings.id')),Column('dropoff_odometer_reading_id',UUID(as_uuid=True),ForeignKey('trip_odometer_readings.id')),Column('passenger_distance_km',Numeric(12,1)),Column('waiting_minutes',Integer),Column('status',String(20)),Column('total_amount',Numeric(12,2)),Column('currency',CHAR(3)),Column('calculated_at',DateTime(timezone=True)),Column('finalized_at',DateTime(timezone=True)),Column('finalized_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('snapshot_hash',CHAR(64)))
trip_fare_line_items_table=table('trip_fare_line_items',Column('fare_calculation_id',UUID(as_uuid=True),ForeignKey('trip_fare_calculations.id')),Column('line_no',SmallInteger),Column('line_type',String(24)),Column('description',String(250)),Column('quantity',Numeric(12,3)),Column('unit_rate',Numeric(12,2)),Column('amount',Numeric(12,2)),Column('source_reference',String(100)))
class TripOperationRun(Base):__table__=trip_operation_runs_table
class TripPickupCredential(Base):__table__=trip_pickup_credentials_table
class TripOperationEvent(Base):__table__=trip_operation_events_table
class TripOdometerReading(Base):__table__=trip_odometer_readings_table
class TripWaitingSession(Base):__table__=trip_waiting_sessions_table
class TripExtraStop(Base):__table__=trip_extra_stops_table
class VehicleOperationalExpense(Base):__table__=vehicle_operational_expenses_table
class TripMedia(Base):__table__=trip_media_table
class TripFareCalculation(Base):__table__=trip_fare_calculations_table
class TripFareLineItem(Base):__table__=trip_fare_line_items_table
